    titleFontFile ? `fontfile='${titleFontFile}'` : null,
    `fontsize=${titleFontSize}`,
    `fontcolor=${titleFontColor}`,
    `x=${x}`,
    `y=${Math.max(24, Math.floor(y))}`,
    `box=1`,
    `boxcolor=${titleBoxColor}`,
    `boxborderw=18`,
    `line_spacing=8`,
    `fix_bounds=true`,
    `shadowcolor=black@0.45`,
    `shadowx=2`,
    `shadowy=2`,
    `text_w='min(tw,${maxTextWidth})'`,
