              display: 'flex',
              color: 'white',
              fontSize: 42,
              fontWeight: 700,
              lineHeight: 1.15,
              textShadow: '0 2px 12px rgba(0,0,0,0.4)',
            }}
          >
            {title}
          </div>
        ) : null}
      </div>
    ),
    {
      width: W,
      height: H,
    }
  )
}
